// Explicit mock snapshots: no fallback to a different day.
const snapshotDates=['2026-10-19','2026-10-22','2026-10-25'];let selectedDate='2026-10-25';const originalGames=games.map(g=>({...g}));const filterBeforeDate=filtered;filtered=function(){return snapshotDates.includes(selectedDate)?filterBeforeDate():[]};
function dateControls(){return `<div class="datecontrols"><label style="display:inline;margin:0">数据日期 <input aria-label="数据日期" type="date" value="${selectedDate}" max="2026-10-26" onchange="changeDate(this.value)"></label><button class="secondary" onclick="stepDate(-1)">前一天</button><button class="secondary" ${selectedDate>='2026-10-26'?'disabled':''} onclick="stepDate(1)">后一天</button><button class="link" onclick="changeDate('2026-10-25')">最新可用日期</button><span class="muted">示例快照：10-19、10-22、10-25</span></div>`}
function applySnapshot(){let n=snapshotDates.indexOf(selectedDate);originalGames.forEach((g,i)=>{Object.assign(games[i],g);if(n>=0&&n<2){games[i].rank=g.rank+(2-n)*Math.round(g.up/2);games[i].up=0;games[i].signal='历史快照';games[i].reason='当日排名快照；该日增长信号尚未计算'}})}
function changeDate(value){if(!value){toast('请选择一个日期');return}selectedDate=value;currentPage=1;kind='全部信号';applySnapshot();closeDrawer();render()}
function stepDate(n){let d=new Date(selectedDate+'T00:00:00Z');d.setUTCDate(d.getUTCDate()+n);changeDate(d.toISOString().slice(0,10))}
const listBeforeDate=list;list=function(){listBeforeDate();let count=document.getElementById('resultCount');if(!count)return;count.textContent=`共 ${filtered().length} 款产品 · 数据日期：${selectedDate}（示例快照）`;if(!snapshotDates.includes(selectedDate)){document.getElementById('list').innerHTML='<div class="empty">该日期暂无榜单快照<p>不会使用其他日期的数据替代，也不将缺失数据解释为未上榜。</p><button class="secondary" onclick="changeDate(\'2026-10-25\')">查看最新可用日期 · 2026-10-25</button></div>'}}
const boardBeforeDate=board;board=function(){if(!document.getElementById('boardbody'))return;if(!snapshotDates.includes(selectedDate)){document.getElementById('boardbody').innerHTML=`<div class="empty">${selectedDate} 暂无榜单快照<p>请切换日期，或查看最新可用日期。</p></div>`;return}boardBeforeDate();document.getElementById('boardbody').innerHTML=document.getElementById('boardbody').innerHTML.replaceAll('2026-10-25',selectedDate)};
const renderBeforeDate=render;render=function(){renderBeforeDate();if(page===0){document.querySelector('.toolbar').insertAdjacentHTML('afterbegin',dateControls());let stats=document.querySelectorAll('.stat');if(stats[0])stats[0].querySelector('strong').textContent=snapshotDates.includes(selectedDate)?games.length:'—';if(stats[1])stats[1].querySelector('strong').textContent=snapshotDates.includes(selectedDate)?games.filter(g=>g.formal).length:'—';if(stats[2]){stats[2].querySelector('span').textContent='当日新发现 · 示例';stats[2].querySelector('strong').textContent=selectedDate==='2026-10-25'?2:'—'}}if(page===1){document.querySelector('.toolbar').insertAdjacentHTML('afterbegin',dateControls());board()}};
const drawBeforeDate=draw;draw=function(){drawBeforeDate();if(drawerTab===1){let rows=document.querySelectorAll('#drawerContent table tr');rows.forEach((r,i)=>{if(i){let day=r.cells[0].textContent;if(day>selectedDate)r.remove();else{let base=originalGames[drawerId];r.cells[1].textContent='#'+(base.rank+(2-snapshotDates.indexOf(day))*Math.round(base.up/2))}}});document.querySelector('#drawerContent .trend')?.remove();document.querySelector('#drawerContent .notice').textContent=`截至 ${selectedDate} 的历史快照（示例），不展示所选日期之后的排名。`;}}
exportProducts=function(){let data='数据日期,产品,平台,类型,状态,排名,信号\n'+filtered().map(g=>[selectedDate,g.name,g.platform,g.type,g.formal?'正式库':'观察中',g.rank,g.signal].map(x=>'"'+String(x).replaceAll('"','""')+'"').join(',')).join('\n');let u=URL.createObjectURL(new Blob(['\ufeff'+data],{type:'text/csv;charset=utf-8'}));let a=document.createElement('a');a.href=u;a.download=`产品库-${selectedDate}-示例.csv`;a.click();URL.revokeObjectURL(u);toast('已导出所选日期的筛选结果')};
const style=document.createElement('style');style.textContent='.datecontrols{display:flex;align-items:center;gap:8px;flex-wrap:wrap;width:100%;padding-bottom:12px;margin-bottom:3px;border-bottom:1px solid #eef1f5}.datecontrols input{min-width:145px;margin-left:8px}.datecontrols button:disabled{opacity:.4;cursor:default}';document.head.append(style);render();
